% Preallocate solution matrix
U = zeros(Nx, Nt+1);
U(:, 1) = u;

% Time-stepping loop
for n = 1:Nt
    % Periodic boundary conditions
    u_left = u(end);
    u_right = u(1);

    % Finite difference approximations
    u_xx = (circshift(u, -1) - 2*u + circshift(u, 1)) / dx^2;
    u_xx(1) = (u_right - 2*u(1) + u(2)) / dx^2;
    u_xx(end) = (u(end-1) - 2*u(end) + u_left) / dx^2;

    % Update solution
    u_new = u + dt * (u_xx + u.^3);

    % Apply periodic boundary conditions
    u_new(1) = u_new(end);
    u_new(end) = u_new(1);

    % Store the new solution
    U(:, n+1) = u_new;

    % Update the current solution
    u = u_new;
end

% Plot the solution
figure;
surf(t, x, U');
xlabel('Time (t)');
ylabel('Space (x)');
zlabel('Solution (u)');
title('Solution of u_t = u_{xx} + u^3');
```

