   - Plot the solutions for different \( Nx \) and visually inspect them. If the plots look similar and the features of interest (e.g., peaks, valleys) stabilize, you have likely chosen an appropriate \( Nx \).

6. **Computational Cost**:
   - Consider the computational cost. Increasing \( Nx \) will increase the computational time and memory usage. Find a balance between accuracy and computational feasibility.

### Example Implementation

Here is an example MATLAB code to perform a convergence test and determine the optimal \( Nx \):

```matlab
% Parameters
L = 1; % Length of the domain
T = 0.1; % Total time
Nt = 500; % Number of time steps
k = T / Nt; % Time step size
D = 0.03; % Diffusion coefficient

% Initial condition
u0 = @(x) 0.5 * sin(pi * x);

% Function to solve the PDE using FEM
function U = solve_pde(L, T, Nx, Nt, D, u0)
    h = L / (Nx - 1); % Spatial step size
    x = linspace(0, L, Nx);
    t = linspace(0, T, Nt+1);

    % Preallocate solution matrix
    U = zeros(Nx, Nt+1);
    U(:, 1) = u0(x);

    % Finite element basis functions (hat functions)
    function [phi, dphi] = hat_functions(i, x, h)
        phi = zeros(size(x));
        dphi = zeros(size(x));
        for j = 1:length(x)
            if abs(x(j) - (i-1)*h) <= h
                phi(j) = (x(j) - (i-2)*h) / h;
                dphi(j) = 1 / h;
            elseif abs(x(j) - i*h) <= h
                phi(j) = ((i+1)*h - x(j)) / h;
                dphi(j) = -1 / h;
            end
        end
    end

    % Assembly of matrices
    K = zeros(Nx, Nx); % Stiffness matrix
    M = zeros(Nx, Nx); % Mass matrix

    for i = 1:Nx
        [phi, dphi] = hat_functions(i, x, h);
        for j = 1:Nx
            [psi, dpsi] = hat_functions(j, x, h);
            K(i, j) = K(i, j) + D * integral(@(x) dphi .* dpsi, 0, L);
            M(i, j) = M(i, j) + integral(@(x) phi .* psi, 0, L);
        end
    end

    % Time-stepping loop
    for n = 1:Nt
        % Right-hand side vector
        b = M * U(:, n) + k * (D * K * U(:, n) + U(:, n).^3);

        % Solve the linear system
        U(:, n+1) = (M + k * D * K) \ b;

        % Apply periodic boundary conditions
        U(1, n+1) = U(end, n+1);
        U(end, n+1) = U(1, n+1);

        % Check for blow-up
        if max(abs(U(:, n+1))) > 1e6
            disp(['Blow-up detected at time step ', num2str(n)]);
            break;
        end
    end
end

% Test different Nx values
Nx_values = [50, 100, 200, 400];
solutions = cell(length(Nx_values), 1);

for i = 1:length(Nx_values)
    Nx = Nx_values(i);
    solutions{i} = solve_pde(L, T, Nx, Nt, D, u0);
end

% Compute errors between successive solutions
errors = [];
for i = 2:length(solutions)
    U_coarse = solutions{i-1};
    U_fine = solutions{i};
    h_coarse = L / (size(U_coarse, 1) - 1);
    h_fine = L / (size(U_fine, 1) - 1);
    x_coarse = linspace(0, L, size(U_coarse, 1));
    x_fine = linspace(0, L, size(U_fine, 1));

    % Interpolate coarse solution to fine grid
    U_coarse_interp = interp1(x_coarse, U_coarse, x_fine, 'linear', 'extrap');

    % Compute L2-norm of the difference
    error = sqrt(sum((U_coarse_interp - U_fine).^2) * h_fine);
    errors = [errors, error];
end

% Display errors
disp('Errors between successive solutions:');
disp(errors);

% Plot solutions for comparison
figure;
hold on;
for i = 1:length(solutions)
    U = solutions{i};
    x = linspace(0, L, size(U, 1));
    plot(x, U(:, end), '-o', 'DisplayName', ['Nx = ', num2str(Nx_values(i))]);
end
legend show;
xlabel('Space (x)');
ylabel('Solution (u)');
title('Solutions for Different Nx Values at t = 0.1');
grid on;

% Check the value at u(0.2, 0.1)
target_x = 0.2;
for i = 1:length(solutions)
    U = solutions{i};
    x = linspace(0, L, size(U, 1));
    idx = find(x == target_x, 1);
    if ~isempty(idx)
        u_value = U(idx, end);
        disp(['Value at u(0.2, 0.1) for Nx = ', num2str(Nx_values(i)), ': ', num2str(u_value)]);
    else
        disp(['No exact match for x = 0.2 in Nx = ', num2str(Nx_values(i))]);
    end
end
```

### Explanation

1. **Function Definition**:
   - The `solve_pde` function encapsulates the finite element method implementation for solving the PDE.

2. **Test Different \( Nx \) Values**:
   - Solutions are computed for different \( Nx \) values and stored in a cell array.

3. **Compute Errors**:
   - The \( L^2 \)-norm of the difference between successive solutions is computed to assess convergence.

4. **Plot Solutions**:
   - The solutions are plotted for visual inspection.

5. **Check Specific Point**:
   - The value at \( u(0.2, 0.1) \) is checked for each \( Nx \).

