Nx = 100;  % Number of spatial points
T = 10;  % Total time
Nt = 1000;  % Number of time steps
dx = L / (Nx - 1);
dt = T / Nt;  % Time step
c = 2.2;  % Wave speed

% Spatial grid
x = linspace(-L/2, L/2, Nx);

% Initial condition: Gaussian function
u = exp(-(x - 0.5).^2 / 0.01);

