    u_new = zeros(size(u));
    for i = 2:Nx-1
        u_new(i) = u(i) + dt * (u(i+1) - 2*u(i) + u(i-1)) / dx^2 + dt * u(i) * (1 - u(i));
    end
    u = u_new;

    % Plot the solution at specific time intervals
