% Plot the final numerical solution and the analytical solution
figure;
plot(x, u, 'b-', x, U_analytical, 'r--');
title(['Numerical Solution vs Analytical Solution at t = ', num2str(T)]);
xlabel('x');
ylabel('u(x,t)');
legend('Numerical', 'Analytical');
grid on;

% Calculate the error
